// A streak of 1024 taps, the whole per-invocation loop budget, across 0.72 x 0.31 of the
// picture, each tap weighted by a chain of eight dependent transcendental calls seeded by its
// colour. About 1 KiB of WGSL that keeps a GPU busy for a long time per pixel.
fn effect(uv: vec2f, src: vec4f) -> vec4f {
    var acc = vec4f(0.0);
    var total = 0.0;
    var w = 0.5;
    for (var i = 0u; i < 1024u; i++) {
        let s = sample_src(fract(uv + vec2f(f32(i) * 0.0007, f32(i) * 0.0003)));
        w = sin(w * 1.37 + s.r);
        w = cos(w * 1.11 + s.g);
        w = exp(-abs(w) * 0.7);
        w = sqrt(w + 0.01);
        w = sin(w * 2.03 + s.b);
        w = exp(-abs(w));
        w = cos(w * 0.91 + s.a);
        w = sqrt(abs(w) + 0.001);
        acc += s * w;
        total += w;
    }
    return acc / max(total, 0.000001);
}
